pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    GoodCallee good;

    function setUp() public { 
        c = new demo();
        good = new GoodCallee();
    }

    function testFuzz_property(address from, address toAddr, uint256 v, uint256 len) public {
        uint256 n = bound(len, 0, 8);

        address[] memory tos = new address[](n);
        for (uint i = 0; i < n; i++) {
            tos[i] = address(good);
        }

        bool okRef;
        try c.transfer(from, address(good), tos, v) returns (bool ret) {
            okRef = ret;
        } catch {
            okRef = false;
        }

        if (n > 0) {
            assertTrue(okRef);
        } else {
            assertTrue(!okRef);
        }
    }
}

contract GoodCallee {
    event Transferred(address from, address to, uint256 v);
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        emit Transferred(from, to, v);
        return true;
    }
}
